-- ---------- Verificare ----------
-- Ar trebui să vezi 3968 posturi în 20 județe.
SELECT county,
       COUNT(*) FILTER (WHERE position = 'Director')         AS directori,
       COUNT(*) FILTER (WHERE position = 'Director adjunct') AS adjuncti,
       COUNT(*)                                              AS total
FROM vacant_positions
GROUP BY county
ORDER BY county;
